// Title: The White Striped
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

// Simple hash function to create randomness
float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to [0, 1]
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Maintain a 16:9 aspect ratio
    uv.x *= iResolution.x / iResolution.y;

    // Grid parameters
    int columns = 8; // Number of columns
    int rows = 4;    // Number of rows
    vec2 gridSize = vec2(1.0 / float(columns), 1.0 / float(rows));

    // Determine the grid cell of the current pixel
    vec2 cellUV = floor(uv / gridSize);

    // Create a unique ID for each rectangle
    float cellID = cellUV.x + cellUV.y * float(columns);

    // Generate random offsets for each rectangle
    float randomOffset = hash(cellID);

    // Smooth animation using time and randomness
    float t = mod(iTime + randomOffset * 10.0, 6.0); // Randomized timing per rectangle
    float phase = mod(cellID, 3.0); // Phase shift based on cell ID
    float fade = smoothstep(0.0, 1.0, abs(sin((t + phase) * 3.14159 / 3.0)));

    // Determine color based on phase
    vec3 color;
    if (phase < 1.0) {
        color = mix(vec3(0.0), vec3(1.0, 0.0, 0.0), fade); // Black to red
    } else if (phase < 2.0) {
        color = mix(vec3(1.0, 0.0, 0.0), vec3(1.0), fade); // Red to white
    } else {
        color = mix(vec3(1.0), vec3(0.0), fade); // White to black
    }

    // Draw the rectangles
    vec2 uvInCell = fract(uv / gridSize); // UV within the cell
    float inRectangle = step(0.05, uvInCell.x) * step(0.05, uvInCell.y) *
                        step(uvInCell.x, 0.95) * step(uvInCell.y, 0.95); // Border padding
    color *= inRectangle;

    // Output the color
    fragColor = vec4(color, 1.0);
}
